@push('scripts')<script>let di={{ count($rows) }};const productsHtml=`@foreach($products as $p)<option value="{{ $p->id }}" data-price="{{ $p->price }}">{{ addslashes($p->name) }} · {{ addslashes($p->sku) }}</option>@endforeach`;document.getElementById('addDraftItem').onclick=()=>{document.getElementById('draftItems').insertAdjacentHTML('beforeend',`<div class="row g-2 align-items-end draft-item mb-2"><div class="col-md-6"><label class="form-label">Product</label><select class="form-select product-select" name="items[${di}][product_id]" required><option value="">Choose product</option>${productsHtml}</select></div><div class="col-md-2"><label class="form-label">Qty</label><input class="form-control" type="number" min="1" name="items[${di}][quantity]" value="1" required></div><div class="col-md-3"><label class="form-label">Unit price</label><input class="form-control price-input" type="number" min="0" step="0.01" name="items[${di}][unit_price]"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger w-100 remove-item">×</button></div></div>`);di++};document.addEventListener('click',e=>{if(e.target.classList.contains('remove-item')&&document.querySelectorAll('.draft-item').length>1)e.target.closest('.draft-item').remove()});document.addEventListener('change',e=>{if(e.target.classList.contains('product-select')){let o=e.target.selectedOptions[0];let price=e.target.closest('.draft-item').querySelector('.price-input');if(!price.value)price.value=o.dataset.price||''}});document.getElementById('draftCustomer').addEventListener('change',function(){let o=this.selectedOptions[0];if(o.value){draftName.value=o.dataset.name||'';draftEmail.value=o.dataset.email||'';draftPhone.value=o.dataset.phone||''}});</script>@endpush
